from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = m
            extra = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p

                if i == n - 1:
                    if need > extra:
                        moves -= 2 * (need - extra) - 1
                else:
                    if need <= extra:
                        moves -= 1
                        extra = 0
                    else:
                        add = need - extra
                        moves -= 2 * add - 1
                        extra = add - 1

                if moves < 0:
                    return False

            return True

        left, right = 0, min(points) * ((m + 1) // 2 + 1)

        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

        return left
